import React from 'react';
import { useTranslation } from 'react-i18next';

// --- DashboardMenuButton (NEW SEPARATE component for the side menu) ---
const DashboardMenuButton = ({ onMenuClick, isEasyMode, t }) => ( 
    <div style={{ 
        position: 'absolute', // Position the button at the very top right of the screen
        top: '15px', 
        right: '15px',
        zIndex: 100, // Ensure it's above everything else
    }}>
        <button
            onClick={onMenuClick}
            style={{ 
                padding: '8px',
                backgroundColor: 'transparent', 
                border: 'none', 
                cursor: 'pointer',
                fontSize: isEasyMode ? '36px' : '28px', 
                color: '#333',
                transition: 'color 0.2s',
            }}
            onMouseOver={e => e.currentTarget.style.color = '#1A73E8'} 
            onMouseOut={e => e.currentTarget.style.color = '#333'}
        >
            <span role="img" aria-label={t('general.menu')}>☰</span>
        </button>
    </div>
);
// --- END DashboardMenuButton ---


// --- Icon Component Modification (No changes) ---
const Icon = ({ name, emoji, isActive, onClick, isProminent, isEasyMode, keyName, color = '#1A73E8', bgColor = '#E8F0FE' }) => {
    // ... Icon logic and styling remain the same ...
    const isColored = isActive || isProminent; 
    let iconColor = color;
    let iconBgColor = '#E8F0FE'; 
    
    if (keyName === "dashboard.emergency_info_card") {
        iconColor = '#DC3545';
        iconBgColor = '#FDE9E9';
    } else if (keyName === "medical_menu.access_card_short") {
        iconColor = '#1A73E8';
        iconBgColor = '#E8F0FE';
    } else if (keyName === "dashboard.medical_history_card") {
        iconColor = '#17A2B8';
        iconBgColor = '#E8F7F9';
    }
    
    const baseFontSize = isEasyMode ? 32 : 18;
    let labelFontSize = baseFontSize;

    if (name && name.length > 12) {
        labelFontSize = isEasyMode ? 24 : 16;
    }


    return (
        <div 
            onClick={onClick} 
            style={{
                padding: '25px', 
                margin: '15px',
                border: `5px solid ${isColored ? iconColor : '#e0e0e0'}`,
                borderRadius: '15px', 
                width: '40%',
                textAlign: 'center',
                backgroundColor: isColored ? iconBgColor : '#ffffff',
                filter: isColored ? 'none' : 'grayscale(80%)',
                opacity: isColored ? 1 : 0.7, 
                cursor: 'pointer',
                boxShadow: isColored ? `0 8px 15px ${iconColor}4D` : '0 2px 5px rgba(0, 0, 0, 0.1)',
                transition: 'all 0.3s',
                fontSize: `${labelFontSize}px`, 
            }}
        >
            <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
            <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
        </div>
    );
};
// --- END Icon Component Modification ---


function Dashboard({ isEasyMode, goToMedical, onMenuClick, goToEmergencyInfo }) { 
    const { t } = useTranslation();

    const showAppointmentNotification = true; 
    
    // Notification style, now acting as a full-width banner
    const notificationStyle = {
        padding: '15px 25px', 
        paddingLeft: '30px', // Extra padding for the bell icon
        backgroundColor: '#FFF3CD', 
        color: '#856404', 
        cursor: 'pointer',
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderBottomLeftRadius: '10px', 
        borderBottomRightRadius: '10px',
        border: '3px solid #FFC107', // Unified border style
        borderTop: 'none', // Remove top border
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        zIndex: 10,
        animation: 'blink-alert 1.8s infinite alternate', 
        
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'flex-start',
        width: '100%',
        boxSizing: 'border-box',
        // Start the banner content visually lower on the screen
        marginTop: '60px', 
    };


    return (
        <div style={{ position: 'relative' }}>
            
            {/* 1. SEPARATE ABSOLUTELY POSITIONED MENU BUTTON */}
            <DashboardMenuButton onMenuClick={onMenuClick} isEasyMode={isEasyMode} t={t} />

            {/* 2. THE NOTIFICATION BANNER (Starts lower due to marginTop: 60px) */}
            <div style={{ padding: '0 15px', boxSizing: 'border-box' }}>
                {showAppointmentNotification && (
                    <div onClick={goToMedical} style={notificationStyle}>
                        <div style={{
                            display: 'flex', 
                            alignItems: 'center', 
                            marginBottom: '5px'
                        }}>
                            <span role="img" aria-label={t('general.alert')} style={{fontSize: '24px', marginRight: '10px'}}>🔔</span>
                            <span style={{ fontSize: isEasyMode ? '24px' : '16px'}}>{t('dashboard.appointment_soon_alert')}</span>
                        </div>
                        <span style={{ fontSize: isEasyMode ? '32px' : '22px', fontWeight: '900', display: 'block' }}>{t('general.tap_here')}</span>
                    </div>
                )}
            </div>
            {/* END Notification Banner */}


            {/* 3. MAIN ICON GRID - Clean top margin for content below the banner */}
            <div style={{ 
                display: 'flex', 
                flexWrap: 'wrap', 
                justifyContent: 'center', 
                paddingTop: '25px', // Space between the banner and the icons
                paddingBottom: '40px' 
            }}>
                
                {/* Icons... */}
                <Icon 
                    name={t('medical_menu.access_card_short')} 
                    emoji="🏥" 
                    isActive={true} 
                    onClick={goToMedical} 
                    isEasyMode={isEasyMode}
                    keyName={'medical_menu.access_card_short'} 
                />
                
                <Icon 
                    name={t('dashboard.emergency_info_card')} 
                    emoji="🆘" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={goToEmergencyInfo} 
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.emergency_info_card'} 
                />
                
                <Icon 
                    name={t('dashboard.medical_history_card')} 
                    emoji="📜" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={() => console.log('Medical History page route needed.')}
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.medical_history_card'} 
                />
                
                <div style={{ width: '40%', margin: '15px', visibility: 'hidden' }}></div>
            </div>

            {/* CSS Animation (No change needed) */}
            <style jsx>{`
                @keyframes blink-alert {
                    0% { 
                        opacity: 1; 
                        box-shadow: 0 4px 15px rgba(255, 193, 7, 0.6); 
                        border-color: #FFC107;
                    }
                    50% { 
                        opacity: 0.8; 
                        box-shadow: 0 4px 5px rgba(0,0,0,0.1); 
                        border-color: #FFEB3B;
                    }
                    100% { 
                        opacity: 1; 
                        box-shadow: 0 4px 15px rgba(255, 193, 7, 0.6); 
                        border-color: #FFC107;
                    }
                }
            `}</style>
        </div>
    );
}

export default Dashboard;
